evidence.original_sql:
DELETE FROM customers
WHERE email IN (
    SELECT email
    FROM customers
    GROUP BY email
    HAVING COUNT(*) > 1
) AND ctid NOT IN (
    SELECT MIN(ctid)
    FROM customers
    GROUP BY email
    HAVING COUNT(*) > 1
);
ALTER TABLE customers ADD CONSTRAINT customers_email_unique UNIQUE (email);

